import{_ as o,o as r,c as e,a2 as s}from"./chunks/framework.vLhlLNVn.js";const d=JSON.parse('{"title":"第 28 章 公开事故复盘集 — 用真实事件把前 27 章串起来","description":"","frontmatter":{},"headers":[],"relativePath":"28-公开事故复盘集.md","filePath":"28-公开事故复盘集.md"}'),a={name:"28-公开事故复盘集.md"};function n(i,t,l,g,u,p){return r(),e("div",null,[...t[0]||(t[0]=[s('<h1 id="第-28-章-公开事故复盘集-—-用真实事件把前-27-章串起来" tabindex="-1">第 28 章 公开事故复盘集 — 用真实事件把前 27 章串起来 <a class="header-anchor" href="#第-28-章-公开事故复盘集-—-用真实事件把前-27-章串起来" aria-label="Permalink to &quot;第 28 章 公开事故复盘集 — 用真实事件把前 27 章串起来&quot;">​</a></h1><blockquote><p>本章没有 lab，是一套&quot;复盘案例库&quot;。每个案例都来自公开可查证的来源（CVE、厂商官方复盘、执法/安全厂商公开报告），标注它对应的章节，可作为面试时的弹药库——<strong>面试官听腻了八股，讲清楚一个真实事故的因果链是资深候选人的分水岭</strong>。</p></blockquote><h2 id="_28-1-事件一-特斯拉-k8s-挖矿事件-2018" tabindex="-1">28.1 事件一：特斯拉 K8s 挖矿事件（2018） <a class="header-anchor" href="#_28-1-事件一-特斯拉-k8s-挖矿事件-2018" aria-label="Permalink to &quot;28.1 事件一：特斯拉 K8s 挖矿事件（2018）&quot;">​</a></h2><p><strong>来源</strong>：RedLock（后被 Palo Alto 收购）公开报告，广泛被主流媒体报道，可搜索 &quot;Tesla Kubernetes cryptojacking 2018&quot; 验证。</p><p><strong>事件链</strong>：K8s Dashboard 暴露公网且无认证 → 攻击者进入集群拿到云凭证（挂载的 ServiceAccount/节点角色）→ 用云凭证访问 S3（内有 telemetry 数据）→ 在 K8s 里部署挖矿 Pod，挖矿流量经 Cloudflare 隐藏。</p><p><strong>映射章节</strong>：第 20 章（L1 入口层、L2 SA token、L5 网络）、第 16 章（入口权限模型）。</p><p><strong>面试话术</strong>：&quot;这个事件的根因不是&#39;K8s 不安全&#39;，而是默认信任模型与公网暴露的组合。今天的防御顺序我会排：入口最小暴露 → Pod 不自动挂 token → NetworkPolicy 限制出网（挖矿要连矿池，出网白名单能直接掐断盈利路径）→ 云凭证与集群凭证分离。&quot;</p><h2 id="_28-2-事件二-ingressnightmare-cve-2025-1974-系列-2025" tabindex="-1">28.2 事件二：IngressNightmare（CVE-2025-1974 系列，2025） <a class="header-anchor" href="#_28-2-事件二-ingressnightmare-cve-2025-1974-系列-2025" aria-label="Permalink to &quot;28.2 事件二：IngressNightmare（CVE-2025-1974 系列，2025）&quot;">​</a></h2><p><strong>来源</strong>：Kubernetes/ingress-nginx 官方公告与各大安全厂商通告（评分最高 9.8），搜索 &quot;CVE-2025-1974 ingress-nginx&quot; 验证。</p><p><strong>事件链</strong>：ingress-nginx 的 admission webhook 对注解等输入处理不当 → 拥有创建 Ingress 权限的低权限用户可注入配置 → 在 controller 上下文执行代码 → controller 通常可读全集群凭证/访问节点网络 → 集群沦陷。重点是：<strong>攻击者不需要节点 SSH、不需要 cluster-admin，只要能建 Ingress</strong>。</p><p><strong>映射章节</strong>：第 16 章（注解=配置注入面，Gateway API 用带 schema 字段收窄）、第 20 章（RBAC 最小化、admission 链路加固）。</p><p><strong>面试话术</strong>：&quot;它改变了&#39;谁能创建 Ingress&#39;这个问题的量级——注解本质是向特权进程注入配置的通道。缓解不止于升版本：入口对象创建权收敛到平台组+GitOps 单写，注解面自然收紧。&quot;</p><h2 id="_28-3-事件三-cve-2018-1002105-k8s-api-server-提权-2018" tabindex="-1">28.3 事件三：CVE-2018-1002105（K8s API server 提权，2018） <a class="header-anchor" href="#_28-3-事件三-cve-2018-1002105-k8s-api-server-提权-2018" aria-label="Permalink to &quot;28.3 事件三：CVE-2018-1002105（K8s API server 提权，2018）&quot;">​</a></h2><p><strong>来源</strong>：Kubernetes 官方安全公告，历史最高危漏洞之一。</p><p><strong>事件链</strong>：API server 代理 exec/attach 等子资源时连接升级处理缺陷 → 恶意客户端复用与 kubelet 的通道 → 任意已认证用户（哪怕 namespace 级）可向 kubelet 下发请求 → 节点级执行。</p><p><strong>映射章节</strong>：第 25 章（API server 是最高价值目标）、第 20 章（版本跟进是安全工程）、第 27 章（升级纪律）。</p><p><strong>面试话术</strong>：&quot;这是&#39;API server 被攻破=整个集群被攻破&#39;的教科书案例，论证了控制面的安全预算应该按最高价值资产配，也论证了 n-2 升级纪律不是形式主义。&quot;</p><h2 id="_28-4-事件四-aks-控制面连锁故障-多次-2021-2023" tabindex="-1">28.4 事件四：AKS 控制面连锁故障（多次，2021-2023） <a class="header-anchor" href="#_28-4-事件四-aks-控制面连锁故障-多次-2021-2023" aria-label="Permalink to &quot;28.4 事件四：AKS 控制面连锁故障（多次，2021-2023）&quot;">​</a></h2><p><strong>来源</strong>：Azure 官方 AKS status history 与事后沟通记录（多处公开可查），具体细节以微软官方披露为准。</p><p><strong>事件链（模式）</strong>：控制面组件（含 etcd/API 链路）异常 → 大规模集群级 API 不可用 → 依赖 API 的部署/扩容/自愈动作全部暂停，业务数据面多数仍存活。</p><p><strong>映射章节</strong>：第 25 章（&quot;API 挂了但业务在跑&quot;的正确应对）、第 27 章（托管不等于免责）。</p><p><strong>面试话术</strong>：&quot;托管控制面的 SLA 覆盖的是它自己，不是你的业务连续性。我的预案框架：数据面自愈能力盘点（PDB/多副本/跨节点反亲和）+ API 不可用期间的降级手册（明确哪些操作做不了、哪些绕行）+ 冷备重建路径。&quot;</p><h2 id="_28-5-事件五-kubefed-归档-2022-工程事故的慢速版" tabindex="-1">28.5 事件五：KubeFed 归档（2022，工程事故的慢速版） <a class="header-anchor" href="#_28-5-事件五-kubefed-归档-2022-工程事故的慢速版" aria-label="Permalink to &quot;28.5 事件五：KubeFed 归档（2022，工程事故的慢速版）&quot;">​</a></h2><p><strong>来源</strong>：KubeFed 官方仓库归档公告与社区讨论。</p><p><strong>事件链（慢速）</strong>：跨集群分发框架投入大量社区资源 → 差异化策略与状态协调的复杂度无法被抽象收敛 → 维护停滞 → 归档。它不是&quot;故障&quot;而是&quot;方向性失败&quot;，但对选型的杀伤力更大。</p><p><strong>映射章节</strong>：第 18 章（多集群 L4 联邦的代价）、第 23 章（抽象的税）。</p><p><strong>面试话术</strong>：&quot;我把它当负面复盘讲：分发只是多集群 10% 的问题，抽象掉 90% 的差异是被证明不可行的路。选 Karmada 前我会先证明自己真的需要 L4，而不是 L1+GitOps 就够。&quot;</p><h2 id="_28-6-模式库-无单一出处-行业高频" tabindex="-1">28.6 模式库（无单一出处，行业高频） <a class="header-anchor" href="#_28-6-模式库-无单一出处-行业高频" aria-label="Permalink to &quot;28.6 模式库（无单一出处，行业高频）&quot;">​</a></h2><p>这些不是具体事件，是各公司事故集的&quot;保留节目&quot;，面试里可以作为&quot;我见过/处理过这类模式&quot;的素材（如实说明是模式不是亲历）：</p><ol><li><strong>DNS 雪崩</strong>：默认拒绝 egress 忘放行 53 / ndots 放大 / CoreDNS 单点。（第 22 章）</li><li><strong>PDB 缺失 × 节点操作</strong>：drain 或 Spot 回收把无 PDB 服务打成不可用。（第 10/21 章）</li><li><strong>巨型 Secret/ConfigMap 拖垮 etcd</strong>：单对象几百 KB×高频 get/watch 的放大效应。（第 25 章）</li><li><strong>LIST 风暴</strong>：cron 里的全量 kubectl / 巡检 agent 旧版本。（第 26 章）</li><li><strong>升级日才发现 CNI 不兼容</strong>：节点 NotReady，被迫回滚窗口战斗。（第 27 章）</li><li><strong>Sidecar 时序 503</strong>：网格升级后主/边容器启停顺序引发的批量 5xx。（第 17 章）</li><li><strong>gang 缺失的训练死锁</strong>：两个 N 卡作业互相卡死 Pending。（第 19 章）</li><li><strong>Spot 雪崩</strong>：批量回收+无 PDB+无优雅终止的三重奏。（第 21 章）</li><li><strong>conversion webhook 自反故障</strong>：CRD 多版本的 webhook 挂→该资源读写全断。（第 23 章）</li><li><strong>金丝雀 NoData 门禁失效</strong>：门禁形同虚设，发布失败照样全量。（第 24 章）</li></ol><h2 id="_28-7-本章用法" tabindex="-1">28.7 本章用法 <a class="header-anchor" href="#_28-7-本章用法" aria-label="Permalink to &quot;28.7 本章用法&quot;">​</a></h2><ul><li>面试前：每个事件背&quot;一句话事实+因果链+我的防御顺序&quot;三段式。</li><li>培训时：每个事件配对应章节的 lab 做实操演示。</li><li>自查时：把模式库 10 条对着自己集群逐条打勾，勾不掉的就是你的下一个整改项。</li></ul><h2 id="_28-8-自测清单" tabindex="-1">28.8 自测清单 <a class="header-anchor" href="#_28-8-自测清单" aria-label="Permalink to &quot;28.8 自测清单&quot;">​</a></h2><ul><li>[ ] 能脱稿讲 3 个完整事件（来源+因果链+防御）</li><li>[ ] 模式库 10 条里能对每条说出对应章节与一个缓解手段</li><li>[ ] 明确区分&quot;公开事件&quot;与&quot;行业模式&quot;的表达边界（不编造亲历）</li></ul><blockquote><p>调研粮备注：本章刻意只用公开可查证事件，所有事件建议面试前自行搜索原文核一次细节（尤其 CVE 编号与年份），防止转述偏差。</p></blockquote>',35)])])}const h=o(a,[["render",n]]);export{d as __pageData,h as default};
